package org.jsoup.helper;

import org.jsoup.Connection;
import org.junit.Test;

import java.net.MalformedURLException;
import java.net.URL;
import java.io.UnsupportedEncodingException;

import static org.jsoup.Connection.KeyVal;
import static org.junit.Assert.assertEquals;

public class UrlBuilderTest {

    @Test
    public void UrlBuilderConstructorTest() throws MalformedURLException {
        URL inputUrl = new URL("https://www.google.com/");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        assertEquals(urlBuilder.build(), inputUrl);
    }

    @Test(expected = MalformedURLException.class)
    public void UrlBuilderConstructorMalformedUrlExceptionTest() throws MalformedURLException {
        URL inputUrl = new URL("htp:/nonexistent.url");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
    }

    @Test
    public void buildTest() throws MalformedURLException {
        URL inputUrl = new URL("https://www.google.com/");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        assertEquals(urlBuilder.build(), inputUrl);
    }

    @Test
    public void appendKeyValTest() throws MalformedURLException, UnsupportedEncodingException {
        URL inputUrl = new URL("https://www.google.com/");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        KeyVal keyValue = KeyVal.create("key", "value");
        urlBuilder.appendKeyVal(keyValue);
        URL expectedUrl = new URL("https://www.google.com/?key=value");
        assertEquals(urlBuilder.build(), expectedUrl);
    }

    @Test(expected = UnsupportedEncodingException.class)
    public void appendKeyValUnsupportedEncodingExceptionTest() throws MalformedURLException, UnsupportedEncodingException {
        URL inputUrl = new URL("https://www.google.com/");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        KeyVal keyValue = KeyVal.create("k\u00E9y", "value"); // key with non-ASCII character
        urlBuilder.appendKeyVal(keyValue);
    }
}
